create table public.prescriptions (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,sale_id bigint references public.sales(id) on delete set null,party_id bigint references public.parties(id) on delete set null,image text not null,notes text,status text not null default 'pending',prescription_number text,review_status text not null default 'pending',review_notes text,reviewed_at timestamptz,expires_at date,patient_name text,patient_phone text,doctor_name text,doctor_license text,used_at timestamptz,meta jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,prescription_number));
create table public.insurance_companies (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,name text not null,code text not null,contact_person text,phone text,email text,address text,city text,country text,tax_id text,status text not null default 'active',integration_type text not null default 'manual',api_endpoint text,api_credentials text,default_coverage_percent numeric(5,2) not null default 80,default_copay_percent numeric(5,2) not null default 20,settlement_days integer not null default 30,notes text,metadata jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,code));
create table public.insurance_policies (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,insurance_company_id bigint not null references public.insurance_companies(id) on delete cascade,customer_id bigint references public.parties(id) on delete set null,policy_number text not null,member_id text,card_number text,holder_name text not null,holder_dob date,holder_gender text,holder_phone text,holder_email text,holder_address text,plan_type text not null default 'individual',status text not null default 'active',start_date date not null,end_date date not null,annual_limit numeric(14,2),used_amount numeric(14,2) not null default 0,remaining_limit numeric(14,2),coverage_percent numeric(5,2),copay_percent numeric(5,2),notes text,metadata jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,policy_number));
create table public.insurance_claims (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,insurance_company_id bigint not null references public.insurance_companies(id) on delete cascade,insurance_policy_id bigint not null references public.insurance_policies(id) on delete cascade,sale_id bigint references public.sales(id) on delete set null,prescription_id bigint references public.prescriptions(id) on delete set null,customer_id bigint references public.parties(id) on delete set null,claim_number text not null,service_date date not null,submission_date date,total_amount numeric(14,2) not null,covered_amount numeric(14,2) not null default 0,patient_responsibility numeric(14,2) not null default 0,approved_amount numeric(14,2),paid_amount numeric(14,2) not null default 0,rejected_amount numeric(14,2) not null default 0,status text not null default 'draft',rejection_reason text,external_reference text,settlement_date date,notes text,line_items jsonb,metadata jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,claim_number));
create table public.loyalty_programs (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,name text not null,points_per_currency integer not null default 1,min_points_for_reward integer not null default 100,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.loyalty_transactions (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,loyalty_program_id bigint not null references public.loyalty_programs(id) on delete cascade,party_id bigint not null references public.parties(id) on delete cascade,points integer not null default 0,type text not null default 'earned',reference_type text,reference_id bigint,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.customer_interactions (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,party_id bigint not null references public.parties(id) on delete cascade,type text not null default 'call',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.batch_lots (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,product_id bigint not null references public.products(id) on delete cascade,batch_number text,lot_number text,manufacture_date date,expiry_date date,recall_date date,supplier_name text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.recall_events (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,product_id bigint references public.products(id) on delete set null,batch_lot_number text,reason text not null,initiated_at date not null,resolved_at date,status text not null default 'active',description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.traceability_logs (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,product_id bigint not null references public.products(id) on delete cascade,batch_lot_number text,from_warehouse_id bigint references public.warehouses(id) on delete set null,to_warehouse_id bigint references public.warehouses(id) on delete set null,type text not null default 'transfer',quantity integer not null default 0,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.stock_audits (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,audit_number text not null,audit_type text not null default 'manual',status text not null default 'pending',audit_date timestamptz,completed_at timestamptz,notes text,metadata jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,audit_number));
do $$ declare t text; begin for t in select unnest(array['prescriptions','insurance_companies','insurance_policies','insurance_claims','loyalty_programs','loyalty_transactions','customer_interactions','batch_lots','recall_events','traceability_logs','stock_audits']) loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on table public.%I from anon,authenticated',t); execute format('grant select,insert,update,delete on table public.%I to authenticated',t); execute format('create policy %I on public.%I for all to authenticated using (business_id=(select private.current_business_id())) with check (business_id=(select private.current_business_id()))',t||'_tenant_policy',t); end loop; end $$;
create index insurance_claims_business_status_idx on public.insurance_claims(business_id,status);
create index batch_lots_business_product_idx on public.batch_lots(business_id,product_id,batch_number);
create index traceability_business_product_idx on public.traceability_logs(business_id,product_id,created_at);